 const createJob=()=>run(async()=>{if((!sourcePath&&!gallerySource)||!target.trim()||!name.trim())throw Error(t('Choose an image, name and target.','Выберите изображение, название и цель.'));const made=gallerySource&&!sourcePath?await rpc({op:'asset-production:create-gallery',input:{name,mode,imageGenerationMode,target,conceptId:gallerySource.conceptId,sourceArtifactId:gallerySource.sourceArtifactId}}):await rpc({op:'asset-production:create',input:{name,mode,imageGenerationMode,target}});if(sourcePath){const imported=await rpc({op:'ingest',kind:'artifact',parentId:made.job.id,paths:[sourcePath]});if(!imported[0]?.id)throw Error(t('Source import failed.','Не удалось импортировать исходник.'));await rpc({op:'asset-production:update',input:{id:made.job.id,expectedRevision:made.job.revision,sourceArtifactId:imported[0].id}});}onGalleryConsumed();await refreshList();await open(made.job.id);});
