 const acceptViewRequirements=()=>run(async()=>{if(!jobId||!ctx)throw new Error(t('Choose an asset job first.','Сначала выберите задание ассета.'));const fresh=await rpc({op:'asset-production:get',id:jobId});if(fresh.job.revision!==ctx.job.revision||fresh.workflow.revision!==ctx.workflow.revision)throw new Error(t('The catalog changed while you were editing. Review the latest catalog and try again.','Каталог изменился во время редактирования. Проверьте актуальный состав и повторите.'));const proposal=fresh.workflow.data.catalogProposal,entries:AssetViewEditorItem[]=proposal?proposal.items:fresh.items.map((entry:Entity)=>({id:entry.id,name:entry.name,route:entry.data.route,dimensions:entry.data.dimensions,views:entry.data.views,viewType:entry.data.viewType,depthEnabled:entry.data.depthEnabled})),items=entries.map(entry=>{const saved=fresh.items.find((value:Entity)=>value.id===entry.id),draft=viewDrafts[entry.id],viewType=draft?draft.viewType||null:entry.viewType||saved?.data.viewType||null,side=viewType==='wall'||viewType==='window'||(draft?draft.side:(entry.views||[]).includes('side')),views=entry.route==='foliage'?['front','back','side','top']:['front',...(side?['side']:[])];return {id:entry.id,name:entry.name,route:entry.route,...(entry.dimensions||saved?.data.dimensions?{dimensions:entry.dimensions||saved?.data.dimensions}:{}),views,...entry.route==='module'?{viewType}:{},depthEnabled:entry.route==='foliage'?false:entry.depthEnabled??saved?.data.depthEnabled??false};});await rpc({op:'asset-production:catalog-accept',input:{id:jobId,expectedJobRevision:fresh.job.revision,expectedWorkflowRevision:fresh.workflow.revision,items,instances:proposal?.instances||fresh.workflow.data.instances,assumptions:proposal?.assumptions||fresh.workflow.data.catalogAssumptions||[]}});await open(jobId);setNotice(t('Composition accepted. Existing images, candidates and placements are preserved.','Состав принят. Существующие изображения, кандидаты и размещения сохранены.'));});
