 const focusAssetCandidate=async(targetItemId:string,targetRole:string,targetCandidateId:string)=>{const fresh=await rpc({op:'asset-production:get',id:jobId}),targetSlot=fresh.workflow.data.slots.find((value:any)=>value.itemId===targetItemId&&value.role===targetRole),targetCandidate=targetSlot?.candidates.find((value:any)=>value.id===targetCandidateId);if(!targetCandidate||targetCandidate.status==='rejected')throw new Error(t('This candidate is no longer available. Refresh the asset job.','Кандидат больше недоступен. Обновите задание ассета.'));await rpc({op:'asset-production:update',input:{id:jobId,expectedRevision:fresh.job.revision,stage:'geometry',selectedItemId:targetItemId,selectedInstanceId:null,selectedRole:targetRole,selectedCandidateId:targetCandidateId,selectedCandidateExplicit:true,selectedSceneCandidateId:null}});const updated=await refresh(jobId!);setStage('geometry');setItemId(targetItemId);setRole(targetRole);setCandidateId(targetCandidateId);setInstanceId('');setSceneId('');selectionReady.current=true;requestAnimationFrame(()=>document.querySelector('[data-testid="asset-return-model-review"], [data-testid="asset-geometry-workflow"]')?.scrollIntoView({behavior:'smooth',block:'center'}));return updated;};
 const retryImportPreview=async(activity:AssetModelImportActivity)=>{const current=importActivityRef.current;if(!current||current.operationId!==activity.operationId||current.state!=='error'||current.stage!=='preview'||!current.artifactId)return;const operationId=crypto.randomUUID(),token=crypto.randomUUID(),message=t('Retrying model preview…','Повторно готовим предпросмотр модели…');updateImportActivity(value=>value?.operationId===current.operationId?{...value,operationId,state:'preview',stage:'preview',startedAt:Date.now(),message,detail:undefined,code:undefined}:value);if(current.phase==='shared-geometry'){setSharedPreviewRetryRequest({operationId,token});return;}const role=current.phase==='geometry'?'geometry':'material',slot=ctx?.workflow.data.slots.find((value:any)=>value.itemId===current.itemId&&value.role===role),candidate=slot?.candidates.find((value:any)=>value.artifactId===current.artifactId&&value.status!=='rejected');if(!candidate){const detail=`Candidate artifact ${current.artifactId} is not present in the current ${role} slot.`;const failure=t('The saved model is no longer in this item’s review slot. Refresh the job before retrying.','Сохранённая модель больше не находится в слоте проверки этой детали. Обновите задание перед повтором.');updateImportActivity(value=>value?.operationId===operationId?{...value,state:'error',message:failure,detail,code:'CANDIDATE_MISSING'}:value);notifyImportFailure(failure,detail,'CANDIDATE_MISSING');return;}try{await focusAssetCandidate(current.itemId,role,candidate.id);if(importActivityRef.current?.operationId===operationId)setAssetPreviewRetryRequest({operationId,token});}catch(error){const diagnostic=assetModelImportDiagnostic(error),failure=t('The model is saved, but the preview could not be retried. Refresh the job and try again.','Модель сохранена, но повторно подготовить предпросмотр не удалось. Обновите задание и повторите попытку.');updateImportActivity(value=>value?.operationId===operationId?{...value,state:'error',message:failure,detail:diagnostic.detail,code:diagnostic.code||'MODEL_PREVIEW_RETRY_FAILED'}:value);notifyImportFailure(failure,diagnostic.detail,diagnostic.code||'MODEL_PREVIEW_RETRY_FAILED');}}; const selectAssetReturnItem=(targetItemId:string,targetRole:'geometry'|'material')=>run(async()=>{const item=ctx?.items.find((value:Entity)=>value.id===targetItemId);if(!item)throw new Error(t('This return item is no longer available. Refresh the job.','Эта деталь больше недоступна для импорта. Обновите задание.'));await update({stage:'geometry',selectedItemId:targetItemId,selectedInstanceId:null,selectedRole:targetRole,selectedCandidateId:null,selectedCandidateExplicit:false,selectedSceneCandidateId:null});setStage('geometry');setItemId(targetItemId);setRole(targetRole);setCandidateId('');setInstanceId('');setSceneId('');selectionReady.current=true;});
