 const acceptBatchReview=()=>run(async()=>{if(!batchReview?.eligible?.length)throw Error(t('There are no current unambiguous image candidates to accept.','Нет актуальных однозначных кандидатов изображений для принятия.'));const updated=await rpc({op:'asset-production:batch-review',input:{id:jobId,expectedJobRevision:batchReview.jobRevision,expectedWorkflowRevision:batchReview.workflowRevision,candidateKeys:batchReview.eligible.map((value:any)=>value.key),candidateVersions:batchReview.eligible.map((value:any)=>({key:value.key,version:value.version}))}});setCtx(updated);setBatchReview(null);setNotice(t(`Accepted ${updated.accepted.length} current candidates.`,`Принято актуальных кандидатов: ${updated.accepted.length}.`));});
  const reviewQueue=(context:any,plan:any,mode:AssetReviewNavigationMode)=>assetReviewNavigationEntries(context,plan,mode);
  const stableReviewSnapshot=async()=>{for(let attempt=0;attempt<3;attempt++){const [plan,fresh]=await Promise.all([rpc({op:'asset-production:batch-review-plan',id:jobId}),rpc({op:'asset-production:get',id:jobId})]);if(plan.jobRevision===fresh.job.revision&&plan.workflowRevision===fresh.workflow.revision)return {plan,fresh};}throw Error(t('The workflow changed while opening review. Refresh the asset job and try again.','Процесс изменился при открытии проверки. Обновите задание ассета и повторите попытку.'));};
