  const decideReviewQueue=(decision:'accept'|'reject')=>run(async()=>{const queue=reviewNavigation,entry=queue?.entries[queue.index];if(!queue||!entry)throw Error(t('Choose a pending candidate first.','Сначала выберите ожидающий кандидат.'));const fresh=await rpc({op:'asset-production:get',id:jobId}),slot=fresh.workflow.data.slots.find((value:any)=>value.itemId===entry.itemId&&value.role===entry.role),candidate=slot?.candidates.find((value:any)=>value.id===entry.candidateId);if(!candidate||candidate.status!=='pending'||candidate.artifactId!==entry.artifactId||candidate.hash!==entry.hash)throw Error(t('This candidate changed. Refresh review before deciding.','Кандидат изменился. Обновите проверку перед решением.'));if(decision==='accept'){const plan=await rpc({op:'asset-production:batch-review-plan',id:jobId}),eligible=plan.eligible.find((value:any)=>value.itemId===entry.itemId&&value.role===entry.role&&value.candidateId===entry.candidateId);if(!eligible)throw Error(t('This image is not current or did not pass technical validation. It remains pending for correction or rejection.','Изображение устарело или не прошло техническую проверку. Оно останется ожидающим исправления или отклонения.'));await rpc({op:'asset-production:batch-review',input:{id:jobId,expectedJobRevision:plan.jobRevision,expectedWorkflowRevision:plan.workflowRevision,candidateKeys:[eligible.key],candidateVersions:[{key:eligible.key,version:eligible.version}]}});}else await rpc({op:'asset-production:review',input:{id:jobId,expectedRevision:fresh.workflow.revision,itemId:entry.itemId,role:entry.role,candidateId:entry.candidateId,decision:'reject'}});const updated=await rpc({op:'asset-production:get',id:jobId});setCtx(updated);await refreshReviewQueue(queue.mode,queue.index);});
  const sameManualLineage=(a:any,b:any)=>!!a&&!!b&&a.itemId===b.itemId&&a.role===b.role&&a.lineage?.jobId===b.lineage?.jobId&&a.lineage?.workflowRevision===b.lineage?.workflowRevision&&a.lineage?.itemRevision===b.lineage?.itemRevision&&a.lineage?.inputFingerprint===b.lineage?.inputFingerprint&&a.lineage?.pairedColorHash===b.lineage?.pairedColorHash&&a.lineage?.pairedSheetHash===b.lineage?.pairedSheetHash;
  const prepareAllManualAssetPrompts=()=>run(async()=>{if(!jobId)throw Error(t('Choose an asset project first.','Сначала выберите проект ассета.'));const latest=await loadManualImageSnapshot(jobId);if(!latest.cards.length)throw Error(t('No image slots are available.','Нет доступных слотов изображений.'));const terminal=await rpc({op:'terminal:status'});if(!terminal.id||terminal.status!=='running'||terminal.assetJobId!==jobId)throw Error(t('Open the Codex terminal for this asset project, then prepare the prompts again.','Откройте терминал Codex для этого проекта ассета и повторите подготовку промптов.'));const result=await rpc({op:'asset-production:manual-image-prompts:prepare-all',workspace,workspaceInstanceId,id:jobId,expectedJobRevision:latest.jobRevision,expectedWorkflowRevision:latest.workflowRevision,terminalId:terminal.id,confirmedIdle:true});setManualImageSnapshot(await loadManualImageSnapshot(jobId));setNotice(t(`Codex was asked to prepare ${result.readyCount} ready prompts. ${result.savedCount} already saved; ${result.blockedCount} waiting for required references.`,`Codex получил запрос на подготовку промптов: ${result.readyCount}. Уже сохранено: ${result.savedCount}; ожидают обязательные референсы: ${result.blockedCount}.`));});  const importManualImage=(card:any,files:FileList)=>run(async()=>{if(files.length!==1)throw Error(t('Choose or drop exactly one image for this view.','Выберите или перетащите ровно одно изображение для этого ракурса.'));if(!card.promptLineageHash||!card.references.length||card.blockedReason)throw Error(card.blockedReason||t('Verified references are required for this exact slot before adding an image.','Перед добавлением изображения для этого слота нужны проверенные референсы.'));const paths=asPaths(files);if(paths.length!==1)throw Error(t('The selected image path is unavailable. Select the file again.','Путь к изображению недоступен. Выберите файл ещё раз.'));const latest=await loadManualImageSnapshot(jobId!);const current=latest.cards.find((value:any)=>value.itemId===card.itemId&&value.role===card.role);if(latest.workflowRevision!==manualImageSnapshot?.workflowRevision||latest.jobRevision!==manualImageSnapshot?.jobRevision||!sameManualLineage(card,current)){setManualImageSnapshot(latest);throw Error(t('The item, view, prompt or paired reference changed. Review the refreshed card, then add the image again.','Деталь, ракурс, промпт или парный референс изменился. Проверьте обновлённую карточку и добавьте изображение ещё раз.'));}const ingested=await rpc({op:'ingest',kind:'artifact',parentId:card.itemId,paths});if(ingested.length!==1||ingested[0]?.error||!ingested[0]?.id)throw Error(ingested[0]?.error||t('The image could not be registered under this asset item.','Не удалось зарегистрировать изображение в этой детали ассета.'));const beforeSubmit=await loadManualImageSnapshot(jobId!),latestCard=beforeSubmit.cards.find((value:any)=>value.itemId===card.itemId&&value.role===card.role);if(beforeSubmit.workflowRevision!==latest.workflowRevision||beforeSubmit.jobRevision!==latest.jobRevision||!sameManualLineage(current,latestCard))throw Error(t('The workflow changed while the file was being checked. The imported file is retained, but no candidate was submitted. Refresh the prompt before retrying.','Процесс изменился во время проверки файла. Импортированный файл сохранён, но кандидат не отправлен. Обновите промпт перед повтором.'));await rpc({op:'asset-production:submit',input:{id:jobId,expectedRevision:beforeSubmit.workflowRevision,outputs:[{itemId:card.itemId,role:card.role,artifactId:ingested[0].id,manualImageContextLineageHash:card.promptLineageHash}]}});setCtx(await rpc({op:'asset-production:get',id:jobId}));setManualImageSnapshot(await loadManualImageSnapshot(jobId!));setNotice(t(`Saved ${card.itemName} · ${roleLabel(card.role)} as a pending candidate for human review.`,`Сохранено: ${card.itemName} · ${roleLabel(card.role)}. Кандидат ожидает проверки человеком.`));});
  const saveManualAssetPrompt=(card:any,value:string)=>run(async()=>{const snapshot=manualImageSnapshot;if(!snapshot)throw Error(t('Refresh the current image slots before saving.','Обновите текущие слоты изображений перед сохранением.'));await rpc({op:'asset-production:manual-image-prompt:save',id:jobId,itemId:card.itemId,role:card.role,expectedJobRevision:snapshot.jobRevision,expectedWorkflowRevision:snapshot.workflowRevision,lineageHash:card.promptLineageHash,prompt:value});const [fresh,updated]=await Promise.all([refresh(jobId!),loadManualImageSnapshot(jobId!)]);setCtx(fresh);setManualImageSnapshot(updated);setNotice(t('Plain-text image prompt saved for this exact slot.','Обычный текстовый промпт сохранён для этого слота.'));});
